print("\n--- FINAL PRODUCTION ACCURACY BENCHMARK ---")
results = []
correct = 0

all_test_data = [(ai_full_texts[i], "AI", f"AI-{i+1}") for i in range(4)] + \
                [(human_full_texts[i], "HUMAN", f"HUMAN-{i+1}") for i in range(4)]

for text, label, tid in all_test_data:
    print(f"Scanning {tid}...")
    res = ensemble_predict(text)
    pred = "AI" if res["verdict"] == "AI GENERATED" else "HUMAN"
    
    is_correct = pred == label
    if is_correct: correct += 1
    
    results.append({
        "id": tid,
        "expected": label,
        "score": res["overall_score"],
        "verdict": res["verdict"],
        "result": "PASSED" if is_correct else "FAILED"
    })

accuracy = (correct / len(all_test_data)) * 100
print(json.dumps(results, indent=2))
print(f"\nFINAL PRODUCTION ACCURACY: {accuracy:.2f}%")
